function shuffledCopyStarts(text: string, pattern: string): number[] {
  const key = [...pattern].sort().join(""), m = pattern.length, out: number[] = [];
  for (let i = 0; i + m <= text.length; i++) {
    if ([...text.slice(i, i + m)].sort().join("") === key) out.push(i);
  }
  return out;
}

