function shuffledCopyStarts(text: string, pattern: string): number[] {
  const n = text.length, m = pattern.length, out: number[] = [];
  if (m > n) return out;
  const need = new Array(26).fill(0), have = new Array(26).fill(0);
  const code = (s: string, i: number) => s.charCodeAt(i) - 97;
  for (let i = 0; i < m; i++) { need[code(pattern, i)]++; have[code(text, i)]++; }
  let matches = 0;
  for (let c = 0; c < 26; c++) if (need[c] === have[c]) matches++;
  // change the window count of letter c by delta and keep 'matches' in sync
  const bump = (c: number, delta: number) => {
    if (have[c] === need[c]) matches--;
    have[c] += delta;
    if (have[c] === need[c]) matches++;
  };
  if (matches === 26) out.push(0);
  for (let i = 1; i + m <= n; i++) {
    bump(code(text, i + m - 1), 1);
    bump(code(text, i - 1), -1);
    if (matches === 26) out.push(i);
  }
  return out;
}

