    def shuffledCopyStarts(self, text: str, pattern: str) -> List[int]:
        n, m = len(text), len(pattern)
        if m > n:
            return []
        need, have = [0] * 26, [0] * 26
        for i in range(m):
            need[ord(pattern[i]) - 97] += 1
            have[ord(text[i]) - 97] += 1
        matches = sum(need[c] == have[c] for c in range(26))
        out = [0] if matches == 26 else []
        for i in range(1, n - m + 1):
            for c, delta in ((ord(text[i + m - 1]) - 97, 1), (ord(text[i - 1]) - 97, -1)):
                if have[c] == need[c]:
                    matches -= 1
                have[c] += delta
                if have[c] == need[c]:
                    matches += 1
            if matches == 26:
                out.append(i)
        return out

